#!/usr/bin/env python3
import argparse
import csv
import hashlib
import json
from collections import Counter
from datetime import datetime, timezone
from pathlib import Path

REQUIRED = {"timestamp", "source", "event_type", "message"}

def parse_timestamp(value):
    dt = datetime.fromisoformat(value.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        raise ValueError("timestamp has no UTC offset")
    return dt.astimezone(timezone.utc)

def sha256_file(path):
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def load_events(path):
    events, errors = [], []
    with path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        missing = REQUIRED - set(reader.fieldnames or [])
        if missing:
            raise ValueError(f"Missing required columns: {sorted(missing)}")
        for row_number, row in enumerate(reader, start=2):
            try:
                row["_dt"] = parse_timestamp(row["timestamp"])
                events.append(row)
            except (TypeError, ValueError) as exc:
                errors.append({"row": row_number, "error": str(exc),
                                "timestamp": row.get("timestamp", "")})
    events.sort(key=lambda row: row["_dt"])
    return events, errors

def hourly_density(events):
    counts = Counter()
    for event in events:
        hour = event["_dt"].replace(minute=0, second=0, microsecond=0)
        counts[hour.isoformat().replace("+00:00", "Z")] += 1
    return dict(sorted(counts.items()))

def correlate(events, target, window_seconds):
    matches = []
    for event in events:
        delta = abs((event["_dt"] - target).total_seconds())
        if delta <= window_seconds:
            matches.append({
                "timestamp": event["timestamp"],
                "source": event["source"],
                "event_type": event["event_type"],
                "message": event["message"],
                "delta_seconds": delta
            })
    return matches

def main():
    parser = argparse.ArgumentParser(
        description="Auditable forensic timeline analysis workbench")
    parser.add_argument("timeline", type=Path)
    parser.add_argument("--output", type=Path, default=Path("timeline_report.json"))
    parser.add_argument("--target")
    parser.add_argument("--window-minutes", type=int, default=5)
    args = parser.parse_args()

    events, errors = load_events(args.timeline)
    report = {
        "input": str(args.timeline),
        "input_sha256": sha256_file(args.timeline),
        "event_count": len(events),
        "parse_errors": errors,
        "time_range": {
            "start": events[0]["_dt"].isoformat() if events else None,
            "end": events[-1]["_dt"].isoformat() if events else None
        },
        "hourly_density": hourly_density(events)
    }

    if args.target:
        target = parse_timestamp(args.target)
        report["correlation"] = {
            "target_utc": target.isoformat(),
            "window_seconds": args.window_minutes * 60,
            "matches": correlate(events, target, args.window_minutes * 60)
        }

    args.output.write_text(json.dumps(report, indent=2, sort_keys=True), encoding="utf-8")
    print(json.dumps(report, indent=2, sort_keys=True))

if __name__ == "__main__":
    main()
